head.script:
Office.onReady(() => {
  // Commands are registered here
});

// ── FILE NOW ──────────────────────────────────────────────────────────────
// Triggered by the "File Email" ribbon button
function fileEmailNow(event) {
  const item = Office.context.mailbox.item;
  const rule = TrisectRules.findMatchingRule(item);

  if (!rule) {
    showNotification(
      "No Rule Found",
      "No project rule matched this email. Open Inbox Manager to add one.",
      "errorMessage"
    );
    event.completed();
    return;
  }

  TrisectRules.moveToFolder(item, rule.folderName, (result) => {
    if (result.success) {
      showNotification(
        "Filed ✓",
        `Moved to "${rule.folderName}" (${rule.name})`,
        "informationalMessage"
      );
    } else {
      showNotification(
        "Could Not File",
        result.error || "Unknown error. Try again or move manually.",
        "errorMessage"
      );
    }
    event.completed();
  });
}

// ── SNOOZE ────────────────────────────────────────────────────────────────
// Snoozes for 1 business day by default
function snoozeEmail(event) {
  const item = Office.context.mailbox.item;
  const snoozeUntil = nextBusinessDay();

  TrisectRules.snoozeItem(item, snoozeUntil).then(() => {
    showNotification(
      "Snoozed",
      `Will reappear on ${snoozeUntil.toLocaleDateString()}`,
      "informationalMessage"
    );
    event.completed();
  }).catch(() => {
    showNotification("Snooze Failed", "Could not save snooze.", "errorMessage");
    event.completed();
  });
}

// ── HELPERS ───────────────────────────────────────────────────────────────

function showNotification(title, message, type) {
  Office.context.mailbox.item.notificationMessages.replaceAsync(
    "trisect_notify",
    {
      type: type || "informationalMessage",
      icon: "Icon.32x32",
      message: `${title}: ${message}`,
      persistent: false,
    }
  );
}

function nextBusinessDay() {
  const d = new Date();
  d.setHours(8, 0, 0, 0);
  d.setDate(d.getDate() + 1);
  // Skip weekend
  if (d.getDay() === 6) d.setDate(d.getDate() + 2); // Sat → Mon
  if (d.getDay() === 0) d.setDate(d.getDate() + 1); // Sun → Mon
  return d;
}
